INSERT INTO site_updates (slug, title, summary, cta_label, cta_href, video_mp4_url, video_webm_url, loop_mp4_url, loop_webm_url, poster_url, captions_vtt_url, is_active, published_at)
VALUES ('handwritten-worked-solutions', 'Handwritten Worked Solutions', 'Get a practice question wrong and watch the full worked solution, written by hand by your teacher. Zoom in, pan around, go full screen.', 'Try a practice question', '/curriculum?c=a-level', '/video/updates/handwritten-worked-solutions/film-1080p-mvs5467h.mp4', '/video/updates/handwritten-worked-solutions/film-1080p-mvs5467h.webm', '/video/updates/handwritten-worked-solutions/loop-720p-mvs5467h.mp4', '/video/updates/handwritten-worked-solutions/loop-720p-mvs5467h.webm', '/video/updates/handwritten-worked-solutions/poster-mvs5467h.webp', '/video/updates/handwritten-worked-solutions/captions-mvs5467h.vtt', true, now())
ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, cta_label = EXCLUDED.cta_label, cta_href = EXCLUDED.cta_href, video_mp4_url = EXCLUDED.video_mp4_url, video_webm_url = EXCLUDED.video_webm_url, loop_mp4_url = EXCLUDED.loop_mp4_url, loop_webm_url = EXCLUDED.loop_webm_url, poster_url = EXCLUDED.poster_url, captions_vtt_url = EXCLUDED.captions_vtt_url,
  is_active = EXCLUDED.is_active, published_at = coalesce(site_updates.published_at, EXCLUDED.published_at), updated_at = now();
